import json
import os
import shutil

from delta.tables import DeltaTable


def layout(path):
    # One row per status: the table's data files and their invoices, from the log. Don't change this.
    files = {}
    log = path + "/_delta_log/"
    for name in sorted(f for f in os.listdir(log) if f.endswith(".json")):
        with open(log + name) as f:
            for line in f:
                action = json.loads(line)
                if "add" in action:
                    add = action["add"]
                    files[add["path"]] = (add["partitionValues"].get("status"), json.loads(add["stats"])["numRecords"])
                if "remove" in action:
                    files.pop(action["remove"]["path"], None)
    by_value = {}
    for value, rows in files.values():
        by_value.setdefault(value, []).append(rows)
    return spark.createDataFrame(
        [(value, len(rows), sum(rows)) for value, rows in by_value.items()],
        "status STRING, files INT, invoices INT",
    )


def build_table(invoices, path):
    # Three daily loads, replayed on a fresh table: each writes one file per status. Don't change this.
    shutil.rmtree(path, ignore_errors=True)  # start from an empty folder on every run
    for day in range(3):
        invoices.coalesce(1).write.format("delta").mode("append").partitionBy("status").save(path)


def compact_closed(path):
    # Compact the closed statuses only.
    pass


def solve(invoices):
    path = "/tmp/billing/invoices"
    build_table(invoices, path)
    compact_closed(path)
    return layout(path)
